172	  buffer.writeln('Flutter crash report; please file at https://github.com/flutter/flutter/issues.\n');
173	
174	  buffer.writeln('## command\n');
175	  buffer.writeln('flutter ${args.join(' ')}\n');
176	
177	  buffer.writeln('## exception\n');
178	  buffer.writeln('${error.runtimeType}: $error\n');
179	  buffer.writeln('```\n$stackTrace```\n');
180	
181	  buffer.writeln('## flutter doctor\n');
182	  buffer.writeln('```\n${await _doctorText()}```');
183	
184	  try {
185	    crashFile.writeAsStringSync(buffer.toString());
186	  } on FileSystemException catch (_) {
187	    // Fallback to the system temporary directory.
188	    crashFile = getUniqueFile(crashFileSystem.systemTempDirectory, 'flutter', 'log');
189	    try {
190	      crashFile.writeAsStringSync(buffer.toString());
191	    } on FileSystemException catch (e) {
192	      printError('Could not write crash report to disk: $e');
193	      printError(buffer.toString());
194	    }
195	  }
196	
197	  return crashFile;
198	}
