19	/// Download a file from the given URL.
20	///
21	/// If a destination file is not provided, returns the bytes.
22	///
23	/// If a destination file is provided, streams the bytes to that file and
24	/// returns an empty list.
25	///
26	/// If [maxAttempts] is exceeded, returns null.
27	Future<List<int>> fetchUrl(Uri url, {
28	  int maxAttempts,
29	  File destFile,
30	}) async {
31	  int attempts = 0;
32	  int durationSeconds = 1;
33	  while (true) {
34	    attempts += 1;
35	    _MemoryIOSink memorySink;
36	    IOSink sink;
37	    if (destFile == null) {
38	      memorySink = _MemoryIOSink();
39	      sink = memorySink;
40	    } else {
41	      sink = destFile.openWrite();
42	    }
43	
44	    final bool result = await _attempt(
45	      url,
46	      destSink: sink,
47	    );
48	    if (result) {
49	      return memorySink?.writes?.takeBytes() ?? <int>[];
50	    }
51	
52	    if (maxAttempts != null && attempts >= maxAttempts) {
53	      printStatus('Download failed -- retry $attempts');
54	      return null;
55	    }
56	    printStatus('Download failed -- attempting retry $attempts in '
57	        '$durationSeconds second${ durationSeconds == 1 ? "" : "s"}...');
58	    await Future<void>.delayed(Duration(seconds: durationSeconds));
59	    if (durationSeconds < 64) {
60	      durationSeconds *= 2;
61	    }
62	  }
63	}
