69	Future<bool> _attempt(Uri url, {
70	  IOSink destSink,
71	  bool onlyHeaders = false,
72	}) async {
73	  assert(onlyHeaders || destSink != null);
74	  printTrace('Downloading: $url');
75	  HttpClient httpClient;
76	  if (context.get<HttpClientFactory>() != null) {
77	    httpClient = context.get<HttpClientFactory>()();
78	  } else {
79	    httpClient = HttpClient();
80	  }
81	  HttpClientRequest request;
82	  HttpClientResponse response;
83	  try {
84	    if (onlyHeaders) {
85	      request = await httpClient.headUrl(url);
86	    } else {
87	      request = await httpClient.getUrl(url);
88	    }
89	    response = await request.close();
90	  } on ArgumentError catch (error) {
91	    final String overrideUrl = platform.environment['FLUTTER_STORAGE_BASE_URL'];
92	    if (overrideUrl != null && url.toString().contains(overrideUrl)) {
93	      printError(error.toString());
94	      throwToolExit(
95	        'The value of FLUTTER_STORAGE_BASE_URL ($overrideUrl) could not be '
96	        'parsed as a valid url. Please see https://flutter.dev/community/china '
97	        'for an example of how to use it.\n'
98	        'Full URL: $url',
99	        exitCode: kNetworkProblemExitCode,);
100	    }
101	    printError(error.toString());
102	    rethrow;
103	  } on HandshakeException catch (error) {
104	    printTrace(error.toString());
105	    throwToolExit(
106	      'Could not authenticate download server. You may be experiencing a man-in-the-middle attack,\n'
107	      'your network may be compromised, or you may have malware installed on your computer.\n'
108	      'URL: $url',
109	      exitCode: kNetworkProblemExitCode,
110	    );
111	  } on SocketException catch (error) {
112	    printTrace('Download error: $error');
113	    return false;
114	  } on HttpException catch (error) {
115	    printTrace('Download error: $error');
116	    return false;
117	  }
118	  assert(response != null);
119	
120	  // If we're making a HEAD request, we're only checking to see if the URL is
121	  // valid.
122	  if (onlyHeaders) {
123	    return response.statusCode == HttpStatus.ok;
124	  }
125	  if (response.statusCode != HttpStatus.ok) {
126	    if (response.statusCode > 0 && response.statusCode < 500) {
127	      throwToolExit(
128	        'Download failed.\n'
129	        'URL: $url\n'
130	        'Error: ${response.statusCode} ${response.reasonPhrase}',
131	        exitCode: kNetworkProblemExitCode,
132	      );
133	    }
134	    // 5xx errors are server errors and we can try again
135	    printTrace('Download error: ${response.statusCode} ${response.reasonPhrase}');
136	    return false;
137	  }
138	  printTrace('Received response from server, collecting bytes...');
139	  try {
140	    assert(destSink != null);
141	    await response.forEach(destSink.add);
142	    return true;
143	  } on IOException catch (error) {
144	    printTrace('Download error: $error');
145	    return false;
146	  } finally {
147	    await destSink?.flush();
148	    await destSink?.close();
149	  }
150	}
